p = "app/controllers/api/v1/tickets_controller.rb"
s = open(p).read()

def rep(old, new):
    global s
    assert s.count(old) == 1, old[:70]
    s = s.replace(old, new)

rep('''        priority = priority_param(input, errors)
''', '''        priority = priority_param(body, errors)
''')

rep('''      # The priority to set, or nil to leave it alone. Only "normal" or "high". A request always has one, so null is refused.
      def priority_param(input, errors)
        return nil unless input.key?(:priority)
        return input[:priority] if Ticket::PRIORITIES.include?(input[:priority])

        errors[:priority] = [ "must be normal or high" ]
        nil
      end
''', '''      # The priority to set, or nil to leave it alone. Only "normal" or "high". A request always has one, so null is
      # refused. This reads the whole body, not the permitted keys, so an object or a list is refused rather than
      # silently ignored.
      def priority_param(body, errors)
        return nil unless body.key?(:priority)
        return body[:priority] if Ticket::PRIORITIES.include?(body[:priority])

        errors[:priority] = [ "must be normal or high" ]
        nil
      end
''')
open(p, "w").write(s)
print("ok")
